"""Consolidate the scoped journal without resubmitting any provider request."""
import json,csv,collections
from pathlib import Path
from auren_curated_probe import atomic,now
RUN=Path('reports/auren-gemini-groq-2026-10-14-r2')
REASONS={
 'operation_outside_scoped_functionality_check':'Não chamada: infraestrutura/batch/cache/contagem ou pesquisa completa fora desta verificação funcional delimitada.',
 'operation_not_used_for_image_model':'Não chamada: operação de chat/genérica não é o contrato escolhido para este gerador de imagens.',
 'native_video_contract_and_price_pending':'Não chamada: Gemini Omni é geração de vídeo; contrato nativo e limite de preço ainda precisam de confirmação. Não foi enviado a chat.',
 'planning_authorization_already_used':'Não chamada novamente: a única sondagem de planejamento autorizada por rota já foi consumida na r1; histórico preservado. Pesquisa completa não autorizada.',
 'native_image_price_bound_unverified':'Não chamada: não foi confirmado um limite de preço por requisição dentro de US$ 0,50.',
 'native_translation_not_supported':'Não chamada: Whisper Turbo não oferece tradução de áudio segundo a documentação oficial.'}
def main():
 complete=json.loads((RUN/'complete.json').read_text());summary=complete['summary'];rows=complete['rows'];snapshot=json.loads((RUN/'snapshot.json').read_text());journal=json.loads((RUN/'results.json').read_text())
 sources=json.loads((RUN/'benchmark-sources-current.json').read_text());bench={r['provider']+':'+r['model']:r for r in sources['routes']}
 aux=sum(s.get('auxiliary_call_count',0) for v in journal['records'].values() for s in v.get('samples',[]))
 summary.update(auxiliary_real_calls=aux,inherited_fixture_generation_calls_not_new=2,scope='Gemini/Groq functionality only; global r1 remains paused.',all_tested=False,all_rows_terminal=all(v.get('terminal') for v in journal['records'].values()))
 grouped={key:[] for key in snapshot['models']}
 for row in rows:
  key=row['provider']+':'+row['requested_model'];grouped[key].append(row);row['benchmark_lookup']={k:bench.get(key,{}).get(k) for k in ('source','scope','benchmark_status')}
  if not row['real_call']:row['pending']=REASONS.get(row.get('blocker'),row['pending'])
 modelrows=[]
 for key,operations in sorted(grouped.items()):
  p,m=key.split(':',1);counts=collections.Counter(r['status'] for r in operations)
  modelrows.append({'provider':p,'model':m,'operations':len(operations),'called_operations':sum(r['native_real_call'] for r in operations),'valid_operations':[r['operation'] for r in operations if r['status']=='valid'],'states':dict(counts),'not_tested_operations':[{'operation':r['operation'],'reason':r['pending']} for r in operations if r['status']=='not_tested']})
 summary['models_with_native_call']=sum(r['called_operations']>0 for r in modelrows);summary['models_without_native_call']=[r['provider']+':'+r['model'] for r in modelrows if not r['called_operations']]
 atomic(RUN/'complete.json',complete);atomic(RUN/'summary.json',summary);atomic(RUN/'model-summary.json',{'at':now(),'models':modelrows})
 fields=list(dict.fromkeys(k for row in rows for k in row if k!='evidence'))
 with (RUN/'complete.csv').open('w',newline='') as f:
  writer=csv.DictWriter(f,fieldnames=fields);writer.writeheader()
  for row in rows:writer.writerow({k:json.dumps(row.get(k),ensure_ascii=False) if isinstance(row.get(k),(dict,list)) else row.get(k) for k in fields})
 lines=['# Auren — verificação delimitada Gemini/Groq, r2','',f'Consolidação: {now()}. Catálogos atuais + IDs exatos anteriores + IDs adicionais documentados. **77 IDs, 492 combinações de provedor/modelo/operação**.','',f'**Não foram todos testados.** {summary["models_with_native_call"]} IDs tiveram operação nativa chamada; {summary["rows_with_native_real_call"]} combinações receberam {summary["real_attempts"]} tentativas, mais {aux} chamadas auxiliares de reconhecimento de voz. Os áudios de referência foram reutilizados; duas gerações de fixtures da rodada anterior não são chamadas novas. Todas as 492 linhas terminaram com resultado ou impedimento explícito.','', '| Estado | Combinações |','|---|---:|']
 lines += [f'| {state} | {count} |' for state,count in summary['by_status'].items()]
 lines += ['',f'Custos positivos informados: {summary["positive_cost_responses"]} respostas. Zero informado: {summary["zero_cost_responses"]}. Custo desconhecido: {summary["unknown_cost_attempts"]} tentativas principais, além das auxiliares sem preço informado. **Isso não é uma fatura de US$ 0.** Limites curtos de tempo/tokens foram usados; cabeçalhos ausentes e erros 429 não medem a cota máxima.','', '## IDs sem nova chamada nativa','']
 lines += ['- '+key for key in summary['models_without_native_call']]
 lines += ['', 'Os três Deep Research já receberam a única tentativa de planejamento autorizada na r1. Omni precisa de contrato/preço de vídeo correto; Nano Banana Pro Preview não teve teto verificável nesta rodada. Estes impedimentos não são provas de mau desempenho. Batch, cache, contagem de tokens e pesquisa completa permanecem não testados nesta rodada; chat genérico não foi usado para aprovar outras modalidades.','', '## Implantação e limites','', 'Éter: Qwen Groq com esforço high, confirmado no worker. Ímpeto: Qwen sem raciocínio para rapidez. Kimi continua candidato efetivo de profundidade; Gemini 3.8 não recebe aprovação por benchmark. Gemini 3.5 Flash-Lite passou no adaptador da Auren para conversa, código, documentos e pesquisa; o worker confirmou também um PDF sintético com identificador não fornecido no pedido. Whisper v3/Turbo foram integrados como alternativas de transcrição e passaram na Auren. Voz pt-BR mantém Magpie; não há segundo transporte de voz pt-BR aprovado no produto. A ordem de todos os 23 perfis está em ../auren-scoped-selection-2026-10-14.json.','', 'O Automático mantém regras locais e usa Qwen com JSON e prazo de 3 s para intenções de ação não reconhecidas. Erro, cota ou JSON inválido retorna à decisão local; não libera cobrança, não executa ferramentas e não envia bytes de anexos ao classificador. Não é garantia de compreender todo pedido.','', 'Imagens: a primeira linha mostra tempo decorrido, posição e estimativa apenas quando disponíveis; a segunda mantém a animação e a etapa. O build passou. Os quatro modelos AI Horde historicamente integrados receberam novas sondagens práticas: quatro imagens de Deliberate/Stable Diffusion falharam na aderência visual, duas AbsoluteReality foram retidas e duas Abyss OrangeMix não concluíram no prazo. Nenhum novo gerador foi aprovado nesta rodada. A elegibilidade anterior de transporte foi preservada para não desativar os perfis; ela não representa aprovação de qualidade atual. Gemini imagem recebeu recusas 429; OpenRouter não mostrou saldo positivo. Tetos financeiros autorizados não foram habilitados como consumo automático.','', 'O navegador integrado não acessou a prévia devido à proteção de acesso local. Não se reduziu esta proteção; a confirmação visual em uma sessão da Auren no computador do usuário permanece pendente. Testes locais de contrato, filtros e apresentação + build são evidências separadas.','', 'A rodada exaustiva geral r1 permanece pausada. Cofre, conversas e alterações locais foram preservados. Os custos desconhecidos são mantidos separados; não houve compra de créditos, cadastro de cartão ou ativação de faturamento.','', '## Inventário por ID','', '| Provedor | Modelo | Operações chamadas | Estados das operações |','|---|---|---:|---|']
 lines += [f'| {r["provider"]} | {r["model"]} | {r["called_operations"]}/{r["operations"]} | '+', '.join(f'{k}: {v}' for k,v in r['states'].items())+' |' for r in modelrows]
 lines += ['', 'As evidências e parâmetros de cada tentativa estão em complete.json; complete.csv contém uma linha por operação. model-summary.json conserva todos os impedimentos por ID. benchmark-sources-current.json contém consulta por ID e ausência de score confirmado. A análise de fontes primárias revisadas está em ../AUREN-BENCHMARKS-GEMINI-GROQ-2026-10-14.md. As sondagens posteriores do adaptador/worker e de imagem têm relatórios separados, não estão misturadas nas 338 tentativas acima.','', 'Retomada: executar run no mesmo diretório conserva tentativas concluídas; não remover blockers nem repetir cobranças sem motivo e limites verificáveis. Arquivos auxiliares herdados de outros provedores servem ao harness; não representam sondagens novas desses provedores.']
 (RUN/'REPORT.md').write_text('\n'.join(lines)+'\n');print('Consolidated',summary['models_with_native_call'],'called model IDs; aux',aux)
if __name__=='__main__':main()
